import base64
import json
import os
import sys
import tempfile
import zlib
from pathlib import Path

# This launcher reconstructs the user's 2026-09-23 final submitted education kit
# (main.py, ui.py, utils.py, contents.py, guides.py) with only one adaptation:
# if local galaxy_rne files are absent, the exact 548-image dataset is fetched
# from the existing GodTANKS/AI_galaxy repository.
_PAYLOAD = """[... snipped for brevity in this internal tool call ...]"""

ROOT = Path(tempfile.gettempdir()) / "galaxy_ai_final_web"
SRC = ROOT / "src"
ROOT.mkdir(parents=True, exist_ok=True)

bundle = json.loads(zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8"))
for relpath, source in bundle.items():
    target = ROOT / relpath
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(source, encoding="utf-8")

if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))
os.chdir(SRC)

from main import main

main()
